mapper.select:
SELECT task.id AS task_id, task.tenant_id AS tenant_id, task.task_type AS task_type, task.status AS task_status, task.progress AS task_progress, task.knowledge_base_id AS knowledge_base_id, kb.name AS knowledge_base_name, task.document_id AS document_id, document.file_name AS document_name, current_step.step_code AS current_step_code, current_step.step_name AS current_step_name, task.error_message AS error_message, task.created_by AS created_by, task.started_at AS started_at, task.finished_at AS finished_at, task.created_at AS created_at, task.updated_at AS updated_at,
CASE WHEN task.started_at IS NULL THEN NULL ELSE GREATEST( 0, FLOOR( EXTRACT( EPOCH FROM ( COALESCE( task.finished_at, CURRENT_TIMESTAMP ) - task.started_at ) ) * 1000 )::bigint ) END AS duration_millis FROM ingestion_task task LEFT JOIN kb_knowledge_base kb ON kb.id = task.knowledge_base_id AND kb.tenant_id = task.tenant_id AND kb.deleted = false
LEFT JOIN kb_document document ON document.id = task.document_id AND document.tenant_id = task.tenant_id AND document.deleted = false LEFT JOIN LATERAL ( SELECT step.step_code, step.step_name FROM ingestion_task_step step WHERE step.task_id = task.id ORDER BY CASE step.status WHEN 'RUNNING' THEN 1 WHEN 'FAILED' THEN 2 WHEN 'PENDING' THEN 3 ELSE 4 END, CASE WHEN step.status = 'PENDING' THEN step.id END ASC, step.id DESC LIMIT 1 ) current_step ON TRUE
task.tenant_id = #{tenantId}
AND task.status = #{request.status}
AND task.task_type = #{request.taskType}
AND task.knowledge_base_id = #{request.knowledgeBaseId}
AND task.document_id = #{request.documentId}
AND task.created_by = #{request.createdBy}
AND task.created_at >= #{request.createdAtStart}
AND task.created_at <= #{request.createdAtEnd}
AND (
task.id = #{keywordTaskId} OR
document.file_name ILIKE CONCAT('%', #{request.keyword}, '%')
OR kb.name ILIKE CONCAT('%', #{request.keyword}, '%') )
ORDER BY task.created_at DESC, task.id DESC

SELECT COUNT(*) AS total_count,

COUNT(*) FILTER (
WHERE task.status = 'PENDING'
) AS pending_count,

COUNT(*) FILTER (
WHERE task.status = 'RUNNING'
) AS running_count,

COUNT(*) FILTER (
WHERE task.status = 'SUCCESS'
) AS success_count,

COUNT(*) FILTER (
WHERE task.status = 'FAILED'
) AS failed_count,

COALESCE(
AVG(
GREATEST(
EXTRACT(
EPOCH FROM (
task.finished_at
- task.started_at
)
) * 1000,
0
)
) FILTER (
WHERE task.status IN (
'SUCCESS',
'FAILED'
)
AND task.started_at IS NOT NULL
AND task.finished_at IS NOT NULL
),
0
)::bigint AS average_duration_millis,

COUNT(*) FILTER (
WHERE task.created_at >= #{todayStart}
) AS today_created_count,

COUNT(*) FILTER (
WHERE task.status = 'SUCCESS'
AND task.finished_at >= #{todayStart}
) AS today_success_count,

COUNT(*) FILTER (
WHERE task.status = 'FAILED'
AND task.finished_at >= #{todayStart}
) AS today_failed_count

FROM ingestion_task task



    task.tenant_id = #{tenantId}


        AND task.knowledge_base_id =
        #{request.knowledgeBaseId}



        AND task.created_at
        >= #{request.createdAtStart}



        AND task.created_at
        <= #{request.createdAtEnd}
